  LegalIndexRecord(code: LegalCode.bns, section: "73", titleEn: "Printing or publishing any matter relating to court proceedings without permission", oldSection: "228A", comparisonNote: "(3) Sub-section of IPC is treated as individual section in BNS with heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "74", titleEn: "Assault or use of criminal force to woman with intent to outrage her modesty", oldSection: "354", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "75", titleEn: "Sexual harassment", oldSection: "354A", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "76", titleEn: "Assault or use of criminal force to woman with intent disrobe", oldSection: "354B", comparisonNote: "Words “Any man who” is replaced by “Whoever”"),
  LegalIndexRecord(code: LegalCode.bns, section: "77", titleEn: "Voyeurism", oldSection: "354C", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bns, section: "78", titleEn: "Stalking", oldSection: "354D", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "79", titleEn: "Word, gesture or act intended to insult 509 the modesty of a woman", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "80", titleEn: "Dowry death", oldSection: "304B", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "81", titleEn: "Cohabitation caused by man deceitfully inducing belief of lawful marriage", oldSection: "493", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "82(1)", titleEn: "Marrying again during lifetime of husband or wife", oldSection: "494", comparisonNote: "IPC section is included as a sub-section"),
  LegalIndexRecord(code: LegalCode.bns, section: "82(2)", titleEn: "Marrying again during lifetime of husband or wife with concealment of former marriage from person with whom subsequent marriage is contracted", oldSection: "495", comparisonNote: "IPC section is included as sub-section in BNS sans heading Words “defined in last preceding section” are excluded"),
  LegalIndexRecord(code: LegalCode.bns, section: "83", titleEn: "Marriage ceremony fraudulently gone 496 through without lawful marriage", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "84", titleEn: "Enticing or taking away or detaining with criminal intent a married Woman", oldSection: "498", comparisonNote: "The words “from that man or from any person having the care of her on behalf of that man” are excluded"),
  LegalIndexRecord(code: LegalCode.bns, section: "85", titleEn: "Husband or relative of husband of a woman subjecting her to cruelty", oldSection: "498A", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "86", titleEn: "Cruelty defined", oldSection: "498A", comparisonNote: "IPC Section 498A has been bifurcated into Explanat Sections 85 and 86. The IPC explanation part ion has been provided in Section 86 BNS under the heading Cruelty defined"),
  LegalIndexRecord(code: LegalCode.bns, section: "87", titleEn: "Kidnapping or abducting in order to 366 murder or for ransom, etc", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "88", titleEn: "Causing miscarriage", oldSection: "312", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "89", titleEn: "Causing miscarriage without woman’s 313 consent", oldSection: "", comparisonNote: "In place of words “defined in last preceding section” previous section number is mentioned in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "90", titleEn: "Death caused by act done with intent to cause miscarriage", oldSection: "314", comparisonNote: "Heading of para-2 “if act done without woman’s consent” is excluded. The words \"Where the act referred to in sub-section (1)” are added"),
  LegalIndexRecord(code: LegalCode.bns, section: "91", titleEn: "Act done with intent to prevent child being born alive or to cause it to die after birth", oldSection: "315", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "92", titleEn: "Causing death of quick unborn child by act amounting to culpable homicide", oldSection: "316", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "93", titleEn: "Exposure and abandonment of child under twelve years, by parent or person having care of it", oldSection: "317", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "94", titleEn: "Concealment of birth by secret disposal of dead body", oldSection: "318", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "95", titleEn: "Hiring, employing or engaging a child - to commit an offence", oldSection: "", comparisonNote: "“Whoever hires, employs or engages any child to commit an offence shall be punished with imprisonment of either description which shall not be less than three years but which may extend to ten years, and with fine; and if the offence be committed shall also be punished with the punishment provided for that offence as if the offence has been committed by such person himself Explanation. —Hiring, employing, engaging or using a child for sexual exploitation or pornography is covered within the meaning of this section”"),
  LegalIndexRecord(code: LegalCode.bns, section: "96", titleEn: "Procuration of child", oldSection: "366A", comparisonNote: "Words “minor girl under the age of eighteen years” are replaced by word “child” and made gender neutral"),
  LegalIndexRecord(code: LegalCode.bns, section: "97", titleEn: "Kidnapping or abducting child under ten years with intent to steal from its person", oldSection: "369", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "98", titleEn: "Selling minor for purposes of prostitution, etc", oldSection: "372", comparisonNote: "“minor” is replaced by “child” in heading and words “any person under the age of eighteen years” are replaced by the word \"child'"),
  LegalIndexRecord(code: LegalCode.bns, section: "99", titleEn: "Buying minor for purposes of prostitution, etc", oldSection: "373", comparisonNote: "Minimum mandatory punishment is introduced as seven years, and the upper limit of imprisonment is extended up to fourteen years in BNS, in place of ten years in IPC Words “any person under the age of eighteen years” are replaced by the word \"child'"),
  LegalIndexRecord(code: LegalCode.bns, section: "100", titleEn: "Culpable homicide", oldSection: "299", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "101", titleEn: "Murder", oldSection: "300", comparisonNote: "Formal changes, but essence is the same, Secondly, thirdly, and fourthly, are replaced by clauses (a), (b), (c), and (d) The word “it” is replaced by the words \"the act by which death is caused\""),
  LegalIndexRecord(code: LegalCode.bns, section: "102", titleEn: "Culpable homicide by causing death of person other than person whose death was intended", oldSection: "301", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "103(1)", titleEn: "Punishment for murder (1)", oldSection: "302", comparisonNote: "No Change, except IPC section is included as subsection in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "103(2)", titleEn: "Punishment for murder (2)", oldSection: "-", comparisonNote: "“When a group of five or more persons acting in concert commits murder on the ground of race, caste or community, sex, place of birth, language, personal belief or any other similar ground each member of such group shall be punished with death or with imprisonment for life, and shall also be liable to fine”"),
  LegalIndexRecord(code: LegalCode.bns, section: "104", titleEn: "Punishment for murder by life- convict", oldSection: "303", comparisonNote: "BNS gives an alternate punishment for the life-convict murderer as death 'or with imprisonment for life, which shall mean the remainder of that person’s natural life', whereas in IPC, only punishment is a death sentence for murder by a life convict"),
  LegalIndexRecord(code: LegalCode.bns, section: "105", titleEn: "Punishment for culpable homicide not 304 amounting to murder", oldSection: "", comparisonNote: "Minimum imprisonment for five years is added and fine is made mandatory"),
  LegalIndexRecord(code: LegalCode.bns, section: "106(1)", titleEn: "Causing death by negligence (1)", oldSection: "304A", comparisonNote: "IPC section is included as subsection in BNS Imprisonment is increased and offence by registered medical practitioner and its explanation are added"),
  LegalIndexRecord(code: LegalCode.bns, section: "106(2)", titleEn: "Causing death by negligence (2)", oldSection: "-", comparisonNote: "This is a new addition, but it will not come into force from 1st July 2024 with other new laws, it is kept on hold"),
  LegalIndexRecord(code: LegalCode.bns, section: "107", titleEn: "Abetment of suicide of child or person 305 of unsound mind", oldSection: "", comparisonNote: "Formal changes but essence is same- 'insane person' is replaced by 'person of unsound mind'"),
  LegalIndexRecord(code: LegalCode.bns, section: "108", titleEn: "Abetment of suicide", oldSection: "306", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "109", titleEn: "Attempt to murder", oldSection: "307", comparisonNote: "Under IPC, Section 307 Clause 2 prescribes the death penalty only for an attempt to murder by a life-convict, but alternate punishment is given in Section 109(2) of the BNS, which states that \"be punished with death or with imprisonment for life, which shall mean the remainder of that person’s natural life\""),
  LegalIndexRecord(code: LegalCode.bns, section: "110", titleEn: "Attempt to commit culpable homicide. 308", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "111", titleEn: "Organized crime", oldSection: "-", comparisonNote: "Newly added section. “Any continuing unlawful activity including kidnapping, robbery, vehicle theft, extortion, land grabbing, contract killing, economic offence, cyber- crimes, trafficking of persons, drugs, weapons or illicit goods or services, human trafficking for prostitution or ransom, by any person or a group of persons acting in concert, singly or jointly, either as a member of an organised crime syndicate or on behalf of such syndicate, by use of violence, threat of violence, intimidation, coercion, or by any other unlawful means to obtain direct or indirect material benefit including a financial benefit, shall constitute organised crime”"),
  LegalIndexRecord(code: LegalCode.bns, section: "112", titleEn: "Petty organized crime", oldSection: "-", comparisonNote: "Newly added section. “Whoever, being a member of a group or gang, either singly or jointly, commits any act of theft, snatching, cheating, unauthorised selling of tickets, unauthorised betting or gambling, selling of public examination question papers or any other similar criminal act, is said to commit petty organised crime”"),
  LegalIndexRecord(code: LegalCode.bns, section: "113", titleEn: "Terrorist act", oldSection: "-", comparisonNote: "Newly added section"),
  LegalIndexRecord(code: LegalCode.bns, section: "114", titleEn: "Hurt", oldSection: "319", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "115(1)", titleEn: "Voluntarily causing hurt (1)", oldSection: "321", comparisonNote: "No Change except IPC section is included as subsection in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "115(2)", titleEn: "Punishment for voluntarily causing (2)", oldSection: "323", comparisonNote: "Section is included as sub-section in BNS sans hurt. heading. Fine is increased (which may extend to ten thousand rupees)"),
  LegalIndexRecord(code: LegalCode.bns, section: "116", titleEn: "Grievous hurt definition", oldSection: "320", comparisonNote: "Suffering threshold period for grievous hurt is reduced from twenty days to fifteen days"),
  LegalIndexRecord(code: LegalCode.bns, section: "117(1)", titleEn: "Voluntarily causing grievous hurt (1)", oldSection: "322", comparisonNote: "No change punishment"),
  LegalIndexRecord(code: LegalCode.bns, section: "117(2)", titleEn: "Punishment for voluntarily causing (2)", oldSection: "325", comparisonNote: "Formal changes but essence is same grievous hurt"),
  LegalIndexRecord(code: LegalCode.bns, section: "117(3)", titleEn: "Voluntarily causing grievous hurt (3)", oldSection: "-", comparisonNote: "New addition. “Whoever commits an offence under sub-section (1) and in the course of such commission causes any hurt to a person which causes that person to be in permanent disability or in persistent vegetative state, shall be punished with rigorous imprisonment for a term which shall not be less than ten years but which may extend to imprisonment for life, which shall mean imprisonment for the remainder of that person’s natural life”"),
  LegalIndexRecord(code: LegalCode.bns, section: "117(4)", titleEn: "Voluntarily causing grievous hurt (4)", oldSection: "-", comparisonNote: "New addition. “When a group of five or more persons acting in concert, causes grievous hurt to a person on the ground of his race, caste or community, sex, place of birth, language, personal belief or any other similar ground, each member of such group shall be guilty of the offence of causing grievous hurt, and shall be punished with imprisonment of either description for a term which may extend to seven years, and shall also be liable to fine”"),
  LegalIndexRecord(code: LegalCode.bns, section: "118(1)", titleEn: "Voluntarily causing hurt or grievous 324 hurt by dangerous weapons or means", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS Fine is increased which may extend to twenty thousand rupees and words “'grievous hurt” are added in heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "118(2)", titleEn: "Voluntarily causing hurt or grievous 326 hurt by dangerous weapons or means", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Mandatory minimum imprisonment for one year is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "119(1)", titleEn: "Voluntarily causing hurt or grievous 327 hurt to extort property, or to constrain to an illegal act", oldSection: "", comparisonNote: "No change except that the IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "119(2)", titleEn: "Voluntarily causing hurt or grievous 329 hurt to extort property, or to constrain to an illegal act", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. The words “any purpose referred to in sub-section (1)” is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "120(1)", titleEn: "Voluntarily causing hurt or grievous 330 hurt to extort confession or to compel restoration of property", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "120(2)", titleEn: "Voluntarily causing grievous hurt to extort confession, or to compel restoration of property", oldSection: "331", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Words “any purpose referred to in sub-section (1)” are added"),
  LegalIndexRecord(code: LegalCode.bns, section: "121(1)", titleEn: "Voluntarily causing hurt to deter public servant from his duty", oldSection: "332", comparisonNote: "IPC section is included as a subsection in BNS. Imprisonment is increased from three to five years"),
  LegalIndexRecord(code: LegalCode.bns, section: "121(2)", titleEn: "Voluntarily causing grievous hurt to deter public servant from his duty", oldSection: "333", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Mandatory minimum imprisonment of one year is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "122(1)", titleEn: "Voluntarily causing provocation hurt on", oldSection: "334", comparisonNote: "IPC section is included as a subsection in BNS. Fine is increased from five hundred to five thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "122(2)", titleEn: "Voluntarily causing grievous hurt on provocation", oldSection: "335", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Imprisonment is increased from four to five years and fine is increased from two thousand to ten thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "123", titleEn: "Causing harm by means of poison etc 328 with intent to commit an offence", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "124(1)", titleEn: "Voluntarily causing grievous hurt by use of acid etc", oldSection: "326A", comparisonNote: "The IPC section is included as a subsection in BNS. Words “causes a person to be in a permanent vegetative state\" are added in Section 124(1) of the BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "124(2)", titleEn: "Voluntarily causing grievous hurt by throwing or attempting to throw acid", oldSection: "326B", comparisonNote: "IPC section is included as a sub-section in BNS, sans heading Words “permanent vegetative state” are added"),
  LegalIndexRecord(code: LegalCode.bns, section: "125", titleEn: "Act endangering life or personal safety of others", oldSection: "336", comparisonNote: "Fine is increased from rupees two hundred and fifty to two thousand five hundred"),
  LegalIndexRecord(code: LegalCode.bns, section: "125(a)", titleEn: "Where hurt is caused", oldSection: "337", comparisonNote: "Fine is increased from five hundred to five thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "125(b)", titleEn: "Where grievous hurt is caused", oldSection: "338", comparisonNote: "Imprisonment is increased from two years to three years and fine is increased from one thousand to ten thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "126(1)", titleEn: "Wrongful restraint", oldSection: "339", comparisonNote: "IPC section is included as a subsection in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "126(2)", titleEn: "Punishment for Wrongful restraint", oldSection: "341", comparisonNote: "IPC section is included as a sub-section in BNS, sans heading. Fine is increased from five hundred rupees to five thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(1)", titleEn: "Wrongful confinement", oldSection: "340", comparisonNote: "IPC section is included as a subsection in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(2)", titleEn: "Punishment for Wrongful confinement", oldSection: "342", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Fine is increased from one thousand to five thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(3)", titleEn: "Wrongful confinement for three or more days", oldSection: "343", comparisonNote: "The IPC section is included as a sub-section in the BNS sans heading. Imprisonment is increased from two years to three years, and the fine is extended up to ten thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(4)", titleEn: "Wrongful confinement for ten or more 344 days", oldSection: "", comparisonNote: "The IPC section is included as a sub-section in the BNS sans heading. Imprisonment is increased from three to five years, and a minimum fine of ten thousand rupees is stipulated"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(5)", titleEn: "Wrongful confinement of person for 345 whose liberation writ has been issued", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Fine is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(6)", titleEn: "Wrongful confinement in secret", oldSection: "346", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. Imprisonment is increased from two to three years and fine is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(7)", titleEn: "Wrongful confinement to extort property, or constrain to illegal act", oldSection: "347", comparisonNote: "No Change except that IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "127(8)", titleEn: "Wrongful confinement to extort confession, or compel restoration of property", oldSection: "348", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. No other change"),
  LegalIndexRecord(code: LegalCode.bns, section: "128", titleEn: "Force", oldSection: "349", comparisonNote: "There is a change in phraseology; also, first, secondly, and thirdly have been replaced with (a), (b), and (c )"),
  LegalIndexRecord(code: LegalCode.bns, section: "129", titleEn: "Criminal force", oldSection: "350", comparisonNote: "No change"),
