  LegalIndexRecord(code: LegalCode.bns, section: "131", titleEn: "Punishment for assault or criminal force otherwise than on grave provocation", oldSection: "352", comparisonNote: "Fine is increased from five hundred to one thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "132", titleEn: "Assault or criminal force to deter public servant from discharge of his duty", oldSection: "353", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "133", titleEn: "Assault or criminal force with intent to dishonour person, otherwise than on grave provocation", oldSection: "355", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "134", titleEn: "Assault or criminal force in attempt to commit theft of property carried by a person", oldSection: "356", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "135", titleEn: "Assault or criminal force in attempt to wrongfully confine a person", oldSection: "357", comparisonNote: "Fine is increased from one thousand to five thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "136", titleEn: "Assault or criminal force on grave provocation", oldSection: "358", comparisonNote: "Fine is increased from two hundred to one thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "137(1)", titleEn: "Kidnapping", oldSection: "359", comparisonNote: "IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "137(1)(a)", titleEn: "Kidnapping from India (a)", oldSection: "360", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bns, section: "137(1)(b)", titleEn: "Kidnapping from lawful guardianship", oldSection: "361", comparisonNote: "The IPC section is included as a clause in the BNS. Words “minor under the age of sixteen years of male or under eighteen years of age if a female” are replaced by “child” thus making it gender neutral"),
  LegalIndexRecord(code: LegalCode.bns, section: "137(2)", titleEn: "Punishment for kidnapping", oldSection: "363", comparisonNote: "IPC section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "138", titleEn: "Abduction", oldSection: "362", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "139", titleEn: "Kidnapping or maiming a child for purposes of begging", oldSection: "", comparisonNote: "363A, The word “minor” is replaced by \"child”. The word \"rigorous\" is added. Imprisonment is extended up to life, i.e., imprisonment for the remainder of that person’s natural life. The clause (b) of sub-section (4) definition is excluded"),
  LegalIndexRecord(code: LegalCode.bns, section: "140(1)", titleEn: "Kidnapping or abducting in order to murder, etc", oldSection: "364", comparisonNote: "No Change except that IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "140(2)", titleEn: "Kidnapping for ransom, etc", oldSection: "364A", comparisonNote: "Section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "140(3)", titleEn: "Kidnapping or abducting with intent secretly and wrongfully to confine person", oldSection: "365", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bns, section: "140(4)", titleEn: "Kidnapping or abducting in order to subject person to grievous hurt, slavery, etc", oldSection: "367", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bns, section: "141", titleEn: "Importation of girl or boy from foreign country", oldSection: "366B", comparisonNote: "Words “any boy under the age of eighteen years” added and “she” is replaced by “girl or boy”"),
  LegalIndexRecord(code: LegalCode.bns, section: "142", titleEn: "Wrongfully concealing or keeping in confinement, kidnapped or abducted person", oldSection: "368", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "143", titleEn: "Trafficking of person", oldSection: "370", comparisonNote: "Word “minor” is replaced by “child”"),
  LegalIndexRecord(code: LegalCode.bns, section: "144", titleEn: "Exploitation of a trafficked person", oldSection: "370A", comparisonNote: "The upper limit of imprisonment is increased from seven years to ten years, and for sub- section (2), from five years to seven years “minor” is replaced by “child”"),
  LegalIndexRecord(code: LegalCode.bns, section: "145", titleEn: "Habitual dealing in slaves", oldSection: "371", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "146", titleEn: "Unlawful compulsory labour", oldSection: "374", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "147", titleEn: "Waging, or attempting to wage war. or 121 abetting waging of war, against the Government of India", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "148", titleEn: "Conspiracy to commit offences punishable by Section 147", oldSection: "121A", comparisonNote: "“and beyond” is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "149", titleEn: "Collecting arms, etc., with intention of 122 waging war against the Government of India", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "150", titleEn: "Concealing with intent to facilitate design to wage war", oldSection: "123", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "151", titleEn: "Assaulting President, Governor, etc., with intent to compel or restrain the exercise of any lawful power", oldSection: "124", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "152", titleEn: "Act endangering sovereignty, unity and integrity of India", oldSection: "-", comparisonNote: "Newly added section. “Whoever, purposely or knowingly, by words, either spoken or written, or by signs, or by visible representation, or by electronic communication or by use of financial mean, or otherwise, excites or attempts to excite, secession or armed rebellion or subversive activities, or encourages feelings of separatist activities or endangers sovereignty or unity and integrity of India; or indulges in or commits any such act shall be punished with imprisonment for life or With imprisonment which may extend to seven years, and shall also be liable to fine.”"),
  LegalIndexRecord(code: LegalCode.bns, section: "153", titleEn: "Waging war against Government of any Foreign State at peace with Government of India", oldSection: "125", comparisonNote: "Words “any Asiatic power in alliance” are replaced by “Government of any foreign State at peace”"),
  LegalIndexRecord(code: LegalCode.bns, section: "154", titleEn: "Committing depredation on territories 126 of Foreign State at peace with Government of India", oldSection: "", comparisonNote: "Words “any power in alliance” are replaced by “any foreign State”"),
  LegalIndexRecord(code: LegalCode.bns, section: "155", titleEn: "Receiving property taken by war or depredation mentioned in Sections 153 and 154", oldSection: "127", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "156", titleEn: "Public servant voluntarily allowing prisoner of State or war to escape", oldSection: "128", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "157", titleEn: "Public servant negligently suffering such prisoner to escape", oldSection: "129", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "158", titleEn: "Aiding escape of, rescuing or harbouring such prisoner", oldSection: "130", comparisonNote: "No change"),
