  LegalIndexRecord(code: LegalCode.bns, section: "341(1)", titleEn: "Making or possessing counterfeit seal, 472 etc., with intent to commit forgery, punishable under section 338", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "341(2)", titleEn: "Making or possessing counterfeit seal, 473 etc., with intent to commit forgery punishable otherwise", oldSection: "", comparisonNote: "IPC section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "341(3)", titleEn: "Possesses any seal, plate or other instrument knowing the same to be counterfeit", oldSection: "New", comparisonNote: "“Whoever possesses any seal, plate or other sub- instrument knowing the same to be section counterfeit, shall be punished with imprisonment of either description for a term which may extend to three years, and shall also be liable to fine”"),
  LegalIndexRecord(code: LegalCode.bns, section: "341(4)", titleEn: "Fraudulently or dishonestly uses as genuine any seal, plate or other instrument knowing or having reason to believe the same to be counterfeit", oldSection: "New", comparisonNote: "“Whoever fraudulently or dishonestly uses as sub- genuine any seal, plate or other instrument section knowing or having reason to believe the same to be counterfeit, shall be punished in the same manner as if he had made or counterfeited such seal, plate or other instrument”"),
  LegalIndexRecord(code: LegalCode.bns, section: "342(1)", titleEn: "Counterfeiting device or mark used for authenticating documents described in section 338, or possessing counterfeit marked material", oldSection: "475", comparisonNote: "IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "342(2)", titleEn: "Counterfeiting device or mark used for authenticating documents described in section 338, or possessing counterfeit marked material", oldSection: "476", comparisonNote: "IPC section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "343", titleEn: "Fraudulent cancellation, destruction, etc. of will, authority to adopt, or valuable security", oldSection: "477", comparisonNote: "No change"),
