  LegalIndexRecord(code: LegalCode.bns, section: "348", titleEn: "Making or possession of any instrument for counterfeiting a property mark", oldSection: "485", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "349", titleEn: "Selling goods marked with counterfeit 486 property mark", oldSection: "", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "350(1)", titleEn: "Making a false mark upon any receptacle containing goods", oldSection: "487", comparisonNote: "IPC section is included as a sub-section in BNS"),
  LegalIndexRecord(code: LegalCode.bns, section: "350(2)", titleEn: "Punishment for making use of any such false mark", oldSection: "488", comparisonNote: "IPC section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "351(1)", titleEn: "Criminal intimidation", oldSection: "503", comparisonNote: "IPC section is included as a sub-section in BNS. “by any means” is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "351(2)/", titleEn: "Criminal intimidation punishment (3)", oldSection: "506", comparisonNote: "IPC Section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "351(4)", titleEn: "Criminal intimidation by an anonymous communication", oldSection: "507", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bns, section: "352", titleEn: "Intentional insult with intent to provoke breach of the peace", oldSection: "504", comparisonNote: "Words “in any manner” are added"),
  LegalIndexRecord(code: LegalCode.bns, section: "353", titleEn: "Statements conducing to public mischief", oldSection: "505", comparisonNote: "\" false information” and “including through electronic means” are added"),
  LegalIndexRecord(code: LegalCode.bns, section: "354", titleEn: "Act caused by inducing person to believe that he will be rendered an object of the Divine displeasure", oldSection: "508", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bns, section: "355", titleEn: "Misconduct in public by a drunken person", oldSection: "510", comparisonNote: "Fine is increased from ten rupees to one thousand, or with community service is added"),
  LegalIndexRecord(code: LegalCode.bns, section: "356(1)", titleEn: "Defamation", oldSection: "499", comparisonNote: "IPC Section is included as a sub section"),
  LegalIndexRecord(code: LegalCode.bns, section: "356(2)", titleEn: "Defamation punishment", oldSection: "500", comparisonNote: "IPC section is included as a sub-section in BNS sans heading. “or with community service” is added as an alternate punishment"),
  LegalIndexRecord(code: LegalCode.bns, section: "356(3)", titleEn: "Printing or engraving matter known to 501 be defamatory", oldSection: "", comparisonNote: "IPC Section is included as a sub-section in BNS sans heading"),
  LegalIndexRecord(code: LegalCode.bns, section: "356(4)", titleEn: "Sale of printed or engraved substance 502 containing defamatory matter", oldSection: "", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bns, section: "357", titleEn: "Breach of contract to attend on and supply wants of helpless person", oldSection: "491", comparisonNote: "Fine increased from two hundred rupees to five thousand rupees"),
  LegalIndexRecord(code: LegalCode.bns, section: "358", titleEn: "Repeal and Savings", oldSection: "-", comparisonNote: "This section is a new addition. The Indian Penal Code, 1860, was enacted by the British Colonisers de novo; therefore, the Repeal and Savings Section was not required at all. Vide sub-section(1) and subsequent Government of India notifications, the IPC will be repealed on 1st July 2024. However, sub-sections (2) to (4) stipulate savings related to the repealed code"),
  LegalIndexRecord(code: LegalCode.bnss, section: "1", titleEn: "Short title, extent and commencement", oldSection: "1", comparisonNote: "It contains the Act name, Bharatiya Nagarik Suraksha Sanhita, 2023, and provisions regarding the commencement date"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2", titleEn: "Definitions", oldSection: "2", comparisonNote: "Several new subsections, such as 2(1)(a), 2(1)(b), 2(1)(d), and 2(1)(e), are added, while others, namely 2(f), 2(k), 2(q), and 2(t) of CrPC, are excluded. Furthermore, certain subsections are modified"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(a)", titleEn: "\"audio-video electronic means\"", oldSection: "-", comparisonNote: "Newly added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(b)", titleEn: "\"bail\"", oldSection: "-", comparisonNote: "Newly added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(c)", titleEn: "\"bailable offence\"", oldSection: "", comparisonNote: "2(a)] No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(d)", titleEn: "\"bail bond\"", oldSection: "-", comparisonNote: "Newly added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(e)", titleEn: "\"bond\"", oldSection: "-", comparisonNote: "Newly added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(f)", titleEn: "\"charge\"", oldSection: "", comparisonNote: "2(b)] No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(g)", titleEn: "\"cognizable offence\"", oldSection: "2(c )", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(h)", titleEn: "\"complaint\"", oldSection: "2(d)", comparisonNote: "No change except \"Code\" is replaced with \"Sanhita\" Wherever the word “Code” is used in CrPC, the word “Sanhita” is used in BNSS, therefore, this fact will not be specifically mentioned in this table hereinafter"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(i)", titleEn: "\"electronic communication\"", oldSection: "-", comparisonNote: "Newly added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(j)", titleEn: "\"High Court\"", oldSection: "2(e )", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(k)", titleEn: "\"inquiry\"", oldSection: "2(g)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(l)", titleEn: "\"investigation\" 2(1)(m )", oldSection: "2(h)", comparisonNote: "The term \"Code\" has been substituted with \"Sanhita\" Explanation that in case of inconsistency provisions of Special Act shall prevail \"judicial proceeding\". 2(i) No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(n)", titleEn: "\"local jurisdiction\"", oldSection: "2(j)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(o)", titleEn: "\"non-cognizable offence\"", oldSection: "2(l)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(p)", titleEn: "\"notification\"", oldSection: "2(m)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(q)", titleEn: "\"offence\"", oldSection: "2(n)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(r)", titleEn: "\"officer in charge of a police station\"", oldSection: "2(o)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(s)", titleEn: "\"place\"", oldSection: "2(p)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(t)", titleEn: "\"police report\"", oldSection: "2(r )", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(u)", titleEn: "\"police station\"", oldSection: "2(s)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(v)", titleEn: "\"Public Prosecutor\" 2(1)(w )", oldSection: "2(u)", comparisonNote: "No change \"sub-division\". 2(v) No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(x)", titleEn: "\"summons-case\"", oldSection: "2(w)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(y)", titleEn: "\"victim\"", oldSection: "2", comparisonNote: "(wa) The words \"for which accused person has been charged and the expression victim” are replaced by \"of the accused person\" etc"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(1)(z)", titleEn: "\"warrant-case\"", oldSection: "2(x)", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "2(2)", titleEn: "Words and expressions used", oldSection: "2(y)", comparisonNote: "Words and expressions used in Sanhita but not defined here but defined in Bharatiya Nyaya Sanhita, 2023, and in the Information Technology Act, 2000, shall have the meanings respectively assigned to them in that Act and Sanhita"),
  LegalIndexRecord(code: LegalCode.bnss, section: "3", titleEn: "Construction of references", oldSection: "3", comparisonNote: "CrPC sub-sections 3(1) and 3(2) are excluded; clauses (a) and (b) of sub-section 3(3) are merged and rearranged, having the same meaning except “or of the third class,” and clauses (c) and (d) of sub-section 3(3) CrPC are also excluded in BNSS"),
  LegalIndexRecord(code: LegalCode.bnss, section: "4", titleEn: "Trial of offences under Bharatiya Nyaya Sanhita and other laws", oldSection: "4", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "5", titleEn: "Saving", oldSection: "5", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "6", titleEn: "Classes of Criminal Courts", oldSection: "6", comparisonNote: "Words \"in any Metropolitan area, Metropolitan Magistrates\" are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "7", titleEn: "Territorial divisions", oldSection: "7", comparisonNote: "Proviso related to Metropolitan area, excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "8", titleEn: "Court of Session", oldSection: "9", comparisonNote: "\"Assistant Sessions Judges\" excluded. New subsections (7) and (8) are added. Under the BNSS, the positions of Judicial Magistrate of the third class, Metropolitan Magistrate, and Assistant Session Judges have been abolished, etc Consequential amendments have been effected in various sections, viz. 8, 11, 12, 14, 17, 22, 29, 113, 196, 214, 320, 321, 415, 422, and 436 of the BNSS"),
  LegalIndexRecord(code: LegalCode.bnss, section: "9", titleEn: "Courts of Judicial Magistrates", oldSection: "11", comparisonNote: "The words \"not being a Metropolitan area\" are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "10", titleEn: "Chief Judicial Magistrate and Additional Chief Judicial Magistrate, etc", oldSection: "12", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "11", titleEn: "Special Judicial Magistrates", oldSection: "13", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "12", titleEn: "Local jurisdiction of Judicial Magistrates", oldSection: "14", comparisonNote: "The words \"Metropolitan area\" and Chief Metropolitan Magistrate are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "13", titleEn: "Subordination of Judicial Magistrates", oldSection: "15", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "14", titleEn: "Executive Magistrates", oldSection: "20", comparisonNote: "The words \"in any Metropolitan area, Metropolitan Magistrates\" are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "15", titleEn: "Special Executive Magistrates", oldSection: "21", comparisonNote: "With the new addition, State Government may appoint police officers of the rank Superintendent of Police or equivalent, as Special Executive Magistrates"),
  LegalIndexRecord(code: LegalCode.bnss, section: "16", titleEn: "Local Jurisdiction of Executive Magistrates", oldSection: "22", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "17", titleEn: "Subordination of Executive Magistrates", oldSection: "23", comparisonNote: "The words \"other than the additional District Magistrate\" are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "18", titleEn: "Public Prosecutors", oldSection: "24", comparisonNote: "New proviso is added to subsection (1)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "19", titleEn: "Assistant Public Prosecutors", oldSection: "25", comparisonNote: "The time line of fourteen days for notice to the state government for the appointment of Assistant Public Prosecutor is mentioned. Proviso is reframed but the meaning is same"),
  LegalIndexRecord(code: LegalCode.bnss, section: "20", titleEn: "Directorate of Prosecution", oldSection: "25A", comparisonNote: "The new addition subsection (1) (b) regarding establishment of District Directorate of Prosecution. Subsections (8), (9), (10) and (11) are also newly added etc"),
  LegalIndexRecord(code: LegalCode.bnss, section: "21", titleEn: "Courts by which offences are triable", oldSection: "26", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "22", titleEn: "Sentences which High Courts and Sessions Judges may pass", oldSection: "28", comparisonNote: "Sub Section 28(3) of CrPC is excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "23", titleEn: "Sentences which Magistrates may pass", oldSection: "29", comparisonNote: "Change in amount of fine: ten thousand is replaced by fifty thousand, and five thousand is replaced by ten thousand The explanation of Section 23 defines \"community service.\" Sub-section 29(4) CrPC is excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "24", titleEn: "Sentence of imprisonment in default of fine", oldSection: "30", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "25", titleEn: "Sentence in cases of conviction of several offences at one trial", oldSection: "31", comparisonNote: "Sub section (1) is reframed but the essence is same. In subsection (2) (a) fourteen years is replaced by twenty years"),
  LegalIndexRecord(code: LegalCode.bnss, section: "26", titleEn: "Mode of conferring powers", oldSection: "32", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "27", titleEn: "Powers of officers appointed", oldSection: "33", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "28", titleEn: "Withdrawal of powers", oldSection: "34", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "29", titleEn: "Powers of Judges and Magistrates exercisable by their successors-in-office", oldSection: "35", comparisonNote: "The words \"Additional or Assistant session Judge\" are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "30", titleEn: "Powers of superior officers of police", oldSection: "36", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "31", titleEn: "Public when to assist Magistrates and police", oldSection: "37", comparisonNote: "The words \"railway, canal, telegraph or\" are excluded thereby scope of the provision is broadened"),
  LegalIndexRecord(code: LegalCode.bnss, section: "32", titleEn: "Aid to person, other than police officer, executing warrant", oldSection: "38", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "33", titleEn: "Public to give information of certain offences", oldSection: "39", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "34", titleEn: "Duty of officers employed in connection with the affairs of a village to make certain report", oldSection: "40", comparisonNote: "In subsection (2) (ii), instead of writing BNS sections corresponding to IPC sections, the offence punishable for imprisonment of ten years or more, etc., is mentioned"),
  LegalIndexRecord(code: LegalCode.bnss, section: "35", titleEn: "When police may arrest without warrant", oldSection: "41", comparisonNote: "& A new subsection 7 is added: “No arrest shall be made 41A without prior permission of an officer not below the rank of Deputy Superintendent of Police in case of an offence which is punishable for imprisonment of less than three years and such person is infirm or is above sixty years of age.”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "36", titleEn: "Procedure of arrest and duties of officer making arrest", oldSection: "41B", comparisonNote: "The words \"any other person\" is added are clause (c)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "37", titleEn: "Designated Police Officer", oldSection: "41C", comparisonNote: "Sub-sections (2) and (3) of the CrPC are merged in (1) (b), and provision is given for designating a police officer not below the rank of Assistant Sub-Inspector for the said purpose"),
  LegalIndexRecord(code: LegalCode.bnss, section: "38", titleEn: "Right of arrested person to meet an advocate of his choice during interrogation", oldSection: "41D", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "39", titleEn: "Arrest on refusal to give name and residence", oldSection: "42", comparisonNote: "The words \"his executing a bond with or without sureties\" are replaced by \"bond or bail bond,\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "40", titleEn: "Arrest by private person and procedure on such arrest", oldSection: "43", comparisonNote: "In subsection (1), without unnecessary delay is further specified by \"but within six hours from such arrest.\" In subsection (2), “re-arrest” is replaced by \"take him in custody\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "41", titleEn: "Arrest by Magistrate", oldSection: "44", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "42", titleEn: "Protection of members of the Armed Forces from arrest", oldSection: "45", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "43", titleEn: "Arrest how made", oldSection: "46", comparisonNote: "A new subsection (3) is added regarding the handcuff of a habitual or repeat offender or accused who has committed certain offences mentioned in the sub-section, etc"),
  LegalIndexRecord(code: LegalCode.bnss, section: "44", titleEn: "Search of place entered by person sought to be arrested", oldSection: "47", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "45", titleEn: "Pursuit of offenders into other jurisdictions", oldSection: "48", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "46", titleEn: "No unnecessary restraint", oldSection: "49", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "47", titleEn: "Person arrested to be informed of grounds of arrest and of right to bail", oldSection: "50", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "48", titleEn: "Obligation of person making 50A arrest to inform about the arrest, etc , to relative or friend", oldSection: "", comparisonNote: "The words \"and also to the designated police officer in the district\" are added in subsection (1). In subsection (3), the words \"may be prescribed in this behalf by\" are replaced by \"may, by rules, provide\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "49", titleEn: "Search of arrested person", oldSection: "51", comparisonNote: "No Change except the word \"whenever\" is excluded from clause (ii) of subsection (1)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "50", titleEn: "Power to seize offensive weapons", oldSection: "52", comparisonNote: "The words \"immediately after the arrest is made\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "51", titleEn: "Examination of accused by medical practitioner at the request of police officer", oldSection: "53", comparisonNote: "From sub-section (1), \"not below the rank of sub-inspector\" is excluded, and subsection (3) is newly added regarding the forwarding of examination reports without delay by a medical practitioner to the investigator. In explanation (b), the \"defined in clause (h) of Section 2 of the Indian Medical Council Act, 1956 (102 of 1956)\" is replaced by \"recognised under the National Medical Commission Act, 2019 (30 of 2019),\" and \"the National Medical Register\" is also added as an optional to the State Medical Register"),
  LegalIndexRecord(code: LegalCode.bnss, section: "52", titleEn: "Examination of person accused of rape by medical practitioner", oldSection: "53A", comparisonNote: "The words \"police officer not below the rank of Sub- Inspector\" are replaced by \"any police officer\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "53", titleEn: "Examination of arrested person by medical officer", oldSection: "54", comparisonNote: "A new proviso added to subsection (1) regarding one more examination can be done if it is necessary, in the opinion of the medical practitioner"),
  LegalIndexRecord(code: LegalCode.bnss, section: "54", titleEn: "Identification of person arrested", oldSection: "54A", comparisonNote: "The second proviso is excluded as it is already covered under the first proviso by adding the words \"the identification process shall be recorded by any audio-video electronic means.\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "55", titleEn: "Procedure when police officer deputes subordinate to arrest without warrant", oldSection: "55", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "56", titleEn: "Health and safety of arrested person", oldSection: "55A", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "57", titleEn: "Person arrested to be taken before Magistrate or officer in charge of police station", oldSection: "56", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "58", titleEn: "Person arrested not to be detained more than twenty- four hours", oldSection: "57", comparisonNote: "No change except the words \"whether having jurisdiction or not\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "59", titleEn: "Police to report apprehensions", oldSection: "58", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "60", titleEn: "Discharge of person apprehended", oldSection: "59", comparisonNote: "\"Bail\" is replaced with \"bail bond\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "61", titleEn: "Power, on escape, to pursue and retake", oldSection: "60", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "62", titleEn: "Arrest to be made strictly according to the Sanhita", oldSection: "60A", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "63", titleEn: "Form of summons", oldSection: "61", comparisonNote: "A new clause (ii) “in an encrypted or any other form of electronic communication and shall bear the image of the seal of the Court or digital signature” is added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "64", titleEn: "Summons how served", oldSection: "62", comparisonNote: "Two new provisos regarding electronic communication, under subsections (1) and (2), are added The word \"personally\" is added in sub-section (3)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "65", titleEn: "Service of summons on corporate bodies, firms, and societies", oldSection: "63", comparisonNote: "In subsection (1), Director and Manager is added New subsection (2) regarding service of summons on any partner of a firm or other association of individuals"),
  LegalIndexRecord(code: LegalCode.bnss, section: "66", titleEn: "Service when persons summoned cannot be found", oldSection: "64", comparisonNote: "The word “male” is excluded to make the provision gender neutral"),
  LegalIndexRecord(code: LegalCode.bnss, section: "67", titleEn: "Procedure when service cannot be effected as before provided", oldSection: "", comparisonNote: "65 No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "68", titleEn: "Service on Government servant", oldSection: "66", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "69", titleEn: "Service of summons outside local limits", oldSection: "67", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "70", titleEn: "Proof of service in such cases and when serving officer not present", oldSection: "68", comparisonNote: "A new subsection (3) is added, mentioning that service of summons through electronic communication shall be considered duly served, and a copy of such summons shall be attested and kept as proof of service of summons"),
  LegalIndexRecord(code: LegalCode.bnss, section: "71", titleEn: "Service of summons on witness by post", oldSection: "69", comparisonNote: "The words \"by electronic communication or\" are added in subsection (1). In subsection (2) words \"or on the proof of delivery of summons under sub-section (3) of section 70 by electronic communication to the satisfaction of the Court,\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "72", titleEn: "Form of warrant of arrest and duration", oldSection: "70", comparisonNote: "No change"),
