  LegalIndexRecord(code: LegalCode.bnss, section: "97", titleEn: "Search of place suspected to contain stolen property, forged documents, etc", oldSection: "94", comparisonNote: "In clause (a) of subsection (2), \"the Metal Token Act, 1889 (1 of 1889)\" is replaced by \"the Coinage Act, 2011 (11 of 2011).\" BNS sections replace the corresponding \"IPC\" sections"),
