  LegalIndexRecord(code: LegalCode.bnss, section: "103", titleEn: "Persons in charge of closed place to allow search", oldSection: "100", comparisonNote: "In subsection (8) BNS sections replaces corresponding IPC sections"),
  LegalIndexRecord(code: LegalCode.bnss, section: "104", titleEn: "Disposal of things found in search beyond jurisdiction", oldSection: "101", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "105", titleEn: "Recording of search and seizure through audio-video electronic means", oldSection: "-", comparisonNote: "“The process of conducting search of a place or taking possession of any property ,article or thing under this Chapter or under section 185, including preparation of the list of all things seized in the course of such search and seizure and signing of such list by witnesses, shall be recorded through any audio-video electronic means preferably mobile phone and the police officer shall without delay forward such recording to the District Magistrate, Sub-divisional Magistrate or Judicial Magistrate of the first class.”"),
