  LegalIndexRecord(code: LegalCode.bnss, section: "151", titleEn: "Protection against prosecution for acts done under sections 148, 149 and", oldSection: "132", comparisonNote: "The word \"military\" is replaced by \"army\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "152", titleEn: "Conditional order for removal of nuisance", oldSection: "133", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "153", titleEn: "Service or notification of order", oldSection: "134", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "154", titleEn: "Person to whom order is addressed to obey or show cause", oldSection: "135", comparisonNote: "In clause (b) the words \"and such appearance or hearing may be permitted through audio-video conferencing.\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "155", titleEn: "Penalty for failure to comply with section 154", oldSection: "136", comparisonNote: "“such person\" is replaced by \"person against whom an order is made under section 154 \" and BNS section replaces corresponding IPC section"),
  LegalIndexRecord(code: LegalCode.bnss, section: "156", titleEn: "Procedure where existence of public right is denied", oldSection: "137", comparisonNote: "No change"),
