  LegalIndexRecord(code: LegalCode.bnss, section: "162", titleEn: "Magistrate may prohibit repetition or continuance of public nuisance", oldSection: "143", comparisonNote: "The words \"or Deputy Commissioner of Police\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "163", titleEn: "Power to issue order in urgent cases of nuisance or apprehended danger", oldSection: "144", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "164", titleEn: "Procedure where dispute concerning land or water is likely to cause breach of peace", oldSection: "145", comparisonNote: "No change"),
