  LegalIndexRecord(code: LegalCode.bnss, section: "166", titleEn: "Dispute concerning right of use of land or water", oldSection: "147", comparisonNote: "In Explanation the words \"For the purposes of this sub- section\" are added. The word “pleader” is replaced by “advocate”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "167", titleEn: "Local inquiry", oldSection: "148", comparisonNote: "The word “pleader” is replaced by “advocate”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "168", titleEn: "Police to prevent cognizable offences", oldSection: "149", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "169", titleEn: "Information of design to commit cognizable offences", oldSection: "150", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "170", titleEn: "Arrest to prevent the commission of cognizable offences", oldSection: "151", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "171", titleEn: "Prevention of injury to public property", oldSection: "152", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "172", titleEn: "Persons bound to conform to lawful directions of police", oldSection: "-", comparisonNote: "“(1) All persons shall be bound to conform to the lawful directions of a police officer given in fulfilment of any of his duty under this Chapter (2) A police officer may detain or remove any person resisting, refusing, ignoring or disregarding to conform to any direction given by him under sub-section (1) and may either take such person before a Magistrate or, in petty cases, release him as soon as possible within a period of twenty-four hours.”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "173", titleEn: "Information in cognizable cases", oldSection: "154", comparisonNote: "By adding the words \"irrespective of the area where the offence is committed”, the scope is expanded to lodge an FIR. This corresponds to the concept of ‘zero FIR’By adding the word \"by electronic communication,\" thereby it is made contemporary. Clause (ii) is added in subsection (1); this is known as eFIR.Subsection (3) is newly added regarding preliminary inquiry to ascertain whether there exists a prima facie case and proceed for investigation on the prima facie case for the cognizable offences which are made punishable for three years or more but less than seven years\".In subsection (4), the words \"failing which such aggrieved person may make an application to the Magistrate.\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "174", titleEn: "Information as to non- cognizable cases and investigation of such cases", oldSection: "155", comparisonNote: "Clause (ii) in subsection (1) is added regarding forwarding the daily diary report of non-cognizable cases fortnightly to the Magistrate"),
  LegalIndexRecord(code: LegalCode.bnss, section: "175", titleEn: "Police officer's power to investigate cognizable case", oldSection: "156", comparisonNote: "A new proviso to subsection (1) is added. Sub-section (4) is newly added to protect public servants in the course of discharge of public duty against undue harassment, and subsection (3) is also amended according to sub-section(4) of section 173"),
  LegalIndexRecord(code: LegalCode.bnss, section: "176", titleEn: "Procedure for investigation", oldSection: "157", comparisonNote: "In clause (b) of subsection (1), audio-video electronic means are added In subsection (2), the words, \"forward the daily diary report fortnightly to the Magistrate\" are added Sub-section (3) is newly added, which stipulates forensic experts visit the crime scene as mandatory for offences punishable for seven years or more"),
  LegalIndexRecord(code: LegalCode.bnss, section: "177", titleEn: "Report how submitted", oldSection: "158", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "178", titleEn: "Power to hold investigation or preliminary inquiry", oldSection: "159", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "179", titleEn: "Police officer's power to require attendance of witnesses", oldSection: "160", comparisonNote: "In the first proviso, \"sixty-five years\" is replaced by \"sixty years\" and the words \"or a person with acute illness\" are added. One new proviso is added. Thus, the scope of the provision is expanded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "180", titleEn: "Examination of witnesses by police", oldSection: "161", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "181", titleEn: "Statements to police and use thereof", oldSection: "162", comparisonNote: "Heading of the section is changed. BSA sections replace corresponding Indian Evidence Act sections"),
  LegalIndexRecord(code: LegalCode.bnss, section: "182", titleEn: "No inducement to be offered", oldSection: "163", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "183", titleEn: "Recording of confessions and statements", oldSection: "164", comparisonNote: "The newly added first proviso to Section 183(6)(a) provides that statements are to be recorded by a woman Magistrate as far as practicable.A newly added second proviso to Section 183(6)(a) provides for mandatory recording of a statement of witness by Magistrate relating to the offences punishable with imprisonment for ten years or more, imprisonment for life, or with death.The fourth proviso to Section 183(6)(a) provides for the recording of the statement of a temporarily or permanently mentally or physically disabled person through audio-video electronic means"),
  LegalIndexRecord(code: LegalCode.bnss, section: "184", titleEn: "Medical examination of the victim of rape", oldSection: "164A", comparisonNote: "\"without delay\" is replaced by \"Within a period of seven days\" for medical practitioner to forward the report to Investigating officer"),
  LegalIndexRecord(code: LegalCode.bnss, section: "185", titleEn: "Search by police officer", oldSection: "165", comparisonNote: "A newly added Proviso to Section 185(2) mandates the recoding of search conducted through audio video, or electronic means. Subsection (5) of 185 of BNSS provides that the copies of record made under SubsSection (1) or (3) shall forthwith, but not later than 48 hours, be sent to Magistrate"),
  LegalIndexRecord(code: LegalCode.bnss, section: "186", titleEn: "When officer in charge of police station may require another to issue search- warrant", oldSection: "166", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "187", titleEn: "Procedure when investigation cannot be completed in twenty-four hours", oldSection: "167", comparisonNote: "A new insertion into Subsection (2) of Section 187 of BNSS provides that the Magistrate to whom an accused person is forwarded under this section may, irrespective of whether he has or has no jurisdiction to try the case, after taking into consideration the status of the accused person as to whether he is not released on bail or his bail has not been cancelled, authorise, from time to time, the detention of the accused in such custody as such Magistrate thinks fit, for a term not exceeding fifteen days in the whole, or in parts, at any time during the initial forty days or sixty days out of the detention period of sixty days or ninety days, as the case may be, as provided in sub-section (3)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "188", titleEn: "Report of investigation by subordinate police officer", oldSection: "168", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "189", titleEn: "Release of accused when evidence deficient", oldSection: "169", comparisonNote: "The words \"with or without sureties\" are excluded and \"or bail bond\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "190", titleEn: "Cases to be sent to Magistrate, when evidence is sufficient", oldSection: "170", comparisonNote: "New proviso is added to subsection (1) regarding taking security from accused not in custody before the magistrate and mandate the Magistrate to accept the same"),
  LegalIndexRecord(code: LegalCode.bnss, section: "191", titleEn: "Complainant and witnesses not to be required to accompany police officer and not to be subjected to restraint", oldSection: "171", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "192", titleEn: "Diary of proceedings in investigation", oldSection: "172", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "193", titleEn: "Report of police officer on completion of investigation", oldSection: "173", comparisonNote: "Section 193(2) extends this requirement to complete the investigation within two months, offences under the Provisions of Protection of Children from Sexual Offences Act also [Sections 4, 6, 8, 10, and 12 of POCSO Act, 2012] in addition to offences of rape and gang rape Section 193(3)(i) of the BNSS provides that reports to Magistrate can also be forwarded through electronic communication The newly inserted clause (i) of sub-section 193(3) (i) of BNSS provides that the report shall also contain 'the sequence of custody in the case of electronic devices' Clause 193(3)(ii) of BNSS provides that the police officer shall, within 90 days, inform the progress of investigation by any means including electronic communication to informant or the victim Subsection (8) is newly inserted, which mandates the police officer investigating the case to submit such number of copies of police report for supply to the accused. Proviso to the same authorises electronic communication for this purpose The new proviso to subsection (6) provides for further investigation during the trial with the permission of the Court"),
  LegalIndexRecord(code: LegalCode.bnss, section: "194", titleEn: "Police to enquire and report on suicide, etc", oldSection: "174", comparisonNote: "In subsection (2) \"forthwith\" is replaced by \"within twenty- four hours\" for sending the report to DM and SDM. The word “man” is replaced by “person”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "195", titleEn: "Power to summon persons", oldSection: "175", comparisonNote: "Proviso to Subsection (1) of 195 provides immunity to male persons under the age of fifteen years or above the age of sixty years, or a woman or a mentally or physically disabled persons or a person with acute illness shall not be required to attend at place other than the place where such person resides. However, they can attend at police station willingly"),
  LegalIndexRecord(code: LegalCode.bnss, section: "196", titleEn: "Inquiry by Magistrate into cause of death", oldSection: "176", comparisonNote: "The words \"Judicial Magistrate\" are replaced by \"Magistrate\", and Metropolitan Magistrate is excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "197", titleEn: "Ordinary place of inquiry and trial", oldSection: "177", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "198", titleEn: "Place of inquiry or trial", oldSection: "178", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "199", titleEn: "Offence triable where act is done or consequence ensues", oldSection: "179", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "200", titleEn: "Place of trial where act is an offence by reason of relation to other offence", oldSection: "180", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "201", titleEn: "Place of trial in case of certain offences", oldSection: "181", comparisonNote: "The words \"of being a thug, or murder committed by a thug\" are excluded as definition of Thug and punishment being one are also excluded from the BNS"),
  LegalIndexRecord(code: LegalCode.bnss, section: "202", titleEn: "Offences committed by means of electronic communications, letters, etc", oldSection: "182", comparisonNote: "The words \"electronic communications\" added. BNS sections replace corresponding IPC sections"),
  LegalIndexRecord(code: LegalCode.bnss, section: "203", titleEn: "Offence committed on journey or voyage", oldSection: "183", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "204", titleEn: "Place of trial for offences triable together", oldSection: "184", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "205", titleEn: "Power to order cases to be tried in different sessions divisions", oldSection: "185", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "206", titleEn: "High Court to decide, in case of doubt, district where inquiry or trial shall take place", oldSection: "186", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "207", titleEn: "Power to issue summons or warrant for offence committed beyond local jurisdiction", oldSection: "187", comparisonNote: "The words \"with or without sureties\" are replaced by \"or bail bond\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "208", titleEn: "Offence committed outside India", oldSection: "188", comparisonNote: "The words \"or where the offence is registered in India\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "209", titleEn: "Receipt of evidence relating to offences committed outside India", oldSection: "189", comparisonNote: "The words \"either in physical form or in electronic form\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "210", titleEn: "Cognizance of offences by Magistrates", oldSection: "190", comparisonNote: "The words \"including any complaint filed by a person authorised under any special law\" and \"submitted in any mode including electronic mode \" are added in clause (a ) and (b ) of subsection (1)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "211", titleEn: "Transfer on application of the accused", oldSection: "191", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "212", titleEn: "Making over of cases to Magistrates", oldSection: "192", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "213", titleEn: "Cognizance of offences by Courts of Session", oldSection: "193", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "214", titleEn: "Additional Sessions Judges to try cases made over to them", oldSection: "194", comparisonNote: "No change except words \"or Assistant sessions Judge\" are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "215", titleEn: "Prosecution for contempt of lawful authority of public servants, for offences against public justice and for offences relating to documents given in evidence", oldSection: "195", comparisonNote: "BNS sections replace corresponding IPC sections The words \"or of some other public servant who is authorised by the concerned public servant so to do\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "216", titleEn: "Procedure for witnesses in case of threatening, etc", oldSection: "195A", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "217", titleEn: "Prosecution for offences against the State and for criminal conspiracy to commit such offence", oldSection: "196", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "218", titleEn: "Prosecution of Judges and public servants", oldSection: "197", comparisonNote: "The BNS sections replace the corresponding IPC sections A second proviso to 218(1)(b) is added, which provides that such Government shall take a decision within a period of one hundred and twenty days from the date of receipt of the request for sanction, and in case it fails to do so, the sanction shall be deemed to have been accorded by such Government. This will curb the tendency to help an accused public servant by such delay tactics"),
  LegalIndexRecord(code: LegalCode.bnss, section: "219", titleEn: "Prosecution for offences against marriage", oldSection: "198", comparisonNote: "The Word \"child\" replaces \"minor\" and \"child\" also replaces \"person under the age of 18 years\", \"is an idiot, or a lunatic\" is replaced by \"is of unsound mind or is having intellectual disability requiring higher support needs\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "220", titleEn: "Prosecution of offences under section 498A of the Bharatiya Nyaya Sanhita,", oldSection: "198A", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "221", titleEn: "Cognizance of offence", oldSection: "198B", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "222", titleEn: "Prosecution for defamation", oldSection: "199", comparisonNote: "BNS Chapters and sections replace corresponding IPC Chapters and sections \"child\" replaces \"under the age of eighteen years \" or is of unsound mind replaces \"or is having intellectual disability or is an idiot or a lunatic\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "223", titleEn: "Examination of complainant", oldSection: "200", comparisonNote: "The newly added first proviso to Section 223(1) provides that no cognizance of an offence shall be taken by the Magistrate without giving the accused an opportunity of being heard A new sub-section (2) of Section 223 provides that a Magistrate shall not take cognizance on a complaint against a public servant for any offence alleged to have been committed in the course of the discharge of his official functions or duties unless—(a) such public servant is given an opportunity to make assertions as to the situation that led to the incident so alleged; and (b) a report containing facts and circumstances of the incident from the officer superior to such a public servant is received"),
  LegalIndexRecord(code: LegalCode.bnss, section: "224", titleEn: "Procedure by Magistrate not competent to take cognizance of the case", oldSection: "201", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "225", titleEn: "Postponement of issue of process", oldSection: "202", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "226", titleEn: "Dismissal of complaint", oldSection: "203", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "227", titleEn: "Issue of process", oldSection: "204", comparisonNote: "The new proviso to sub-section (1) of Section 227 provides that summons or warrant may also be issued through electronic means"),
  LegalIndexRecord(code: LegalCode.bnss, section: "228", titleEn: "Magistrate may dispense with personal attendance of accused", oldSection: "205", comparisonNote: "\"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "229", titleEn: "Special summons in cases of petty offence", oldSection: "206", comparisonNote: "\"pleader\" is replaced by \"advocate.\" The threshold amount of fine for the purpose of the definition of \"petty offence\" is increased by this section from one thousand rupees to five thousand rupees. The monetary limit of the fine specified in summons is increased from one thousand rupees to five thousand rupees “the Motor Vehicles Act, 1939 (59 of 1939)” is replaced by “the Motor Vehicles Act, 1988 (59 of 1988).”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "230", titleEn: "Supply to the accused of copy of police report and other documents", oldSection: "207", comparisonNote: "This section states that the documents are to be supplied free of cost to the accused without any delay, and in no case beyond 14 days from the date of production or appearance of the accused, and should also be provided to the victim if represented by an advocate. The last proviso states that the supply of documents in electronic form shall be considered as duly furnished"),
  LegalIndexRecord(code: LegalCode.bnss, section: "231", titleEn: "Supply of copies of statements and documents to accused in other cases triable by Court of Session", oldSection: "208", comparisonNote: "Last proviso states that supply of documents to accused in electronic form shall be considered as duly furnished \"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "232", titleEn: "Commitment of case to Court of Session when offence is triable exclusively by it", oldSection: "209", comparisonNote: "Two new provisos are added herein. By first proviso proceedings have been made time-bound. The proceedings under this section shall be completed within a period of ninety days from the date of taking cognizance, and such period may be extended, by the Magistrate for a period not exceeding one hundred eighty days for the reasons to be recorded in writing Second proviso states that any application filed before the Magistrate by the accused or the victim or any person authorised by such person in a case triable by Court of Session, shall be forwarded to the Court of Session with the committal of the case"),
  LegalIndexRecord(code: LegalCode.bnss, section: "233", titleEn: "Procedure to be followed when there is a complaint case and police investigation in respect of the same offence", oldSection: "210", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "234", titleEn: "Contents of charge", oldSection: "211", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "235", titleEn: "Particulars as to time, place and person", oldSection: "212", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "236", titleEn: "When manner of committing offence must be stated", oldSection: "213", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "237", titleEn: "Words in charge taken in sense of law under which offence is punishable", oldSection: "214", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "238", titleEn: "Effect of errors", oldSection: "215", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "239", titleEn: "Court may alter charge", oldSection: "216", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "240", titleEn: "Recall of witnesses when charge altered", oldSection: "217", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "241", titleEn: "Separate charges for distinct offences", oldSection: "218", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "242", titleEn: "Offences of same kind within year may be charged together", oldSection: "219", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "243", titleEn: "Trial for more than one offence", oldSection: "220", comparisonNote: "Subsection 243(1) reorganises illustrations (b) and (c) given in CrPC, citing \"adultery\" and \"enticing away,\" which are replaced by \"rape\" in the rephrased illustration (b) herein"),
  LegalIndexRecord(code: LegalCode.bnss, section: "244", titleEn: "Where it is doubtful what offence has been committed", oldSection: "221", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "245", titleEn: "When offence proved included in offence charged", oldSection: "222", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "246", titleEn: "What persons may be charged jointly", oldSection: "223", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "247", titleEn: "Withdrawal of remaining charges on conviction on one of several charges", oldSection: "224", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "248", titleEn: "Trial to be conducted by Public Prosecutor", oldSection: "225", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "249", titleEn: "Opening case for prosecution", oldSection: "226", comparisonNote: "The words \"or under any other law for the time being in force\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "250", titleEn: "Discharge", oldSection: "227", comparisonNote: "New subsection (1) provides that the accused may prefer an application for discharge within a period of sixty days from the date of commencement of the case under Section 232"),
  LegalIndexRecord(code: LegalCode.bnss, section: "251", titleEn: "Framing of charge", oldSection: "228", comparisonNote: "The time limit for framing the charge is added as being within a period of sixty days from the date of first hearing This section also allows charges to be read and explained, to the accused “present either physically or through audio- video electronic means.”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "252", titleEn: "Conviction on plea of guilty", oldSection: "229", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "253", titleEn: "Date for prosecution evidence", oldSection: "230", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "254", titleEn: "Evidence for prosecution", oldSection: "231", comparisonNote: "Newly added proviso to section 254 of BNSS provides that evidence of a witness may be recorded by audio-video electronic means Newly added subsection (2) provides that the deposition of evidence of any police officer or public servant may be taken through audio-video electronic means"),
  LegalIndexRecord(code: LegalCode.bnss, section: "255", titleEn: "Acquittal", oldSection: "232", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "256", titleEn: "Entering upon defence", oldSection: "233", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "257", titleEn: "Arguments", oldSection: "234", comparisonNote: "\"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "258", titleEn: "Judgment of acquittal or conviction", oldSection: "235", comparisonNote: "New addition to subsection (1) for time bound disposal- After hearing arguments and points of law (if any), the Judge shall give a judgement in the case, “as soon as possible, within a period of thirty days from the date of completion of arguments, which may be extended, to a period of fortyfive days for reasons to be recorded in writing”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "259", titleEn: "Previous conviction", oldSection: "236", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "260", titleEn: "Procedure in cases instituted under sib-section 2 of section", oldSection: "237", comparisonNote: "Upper limit of compensation amount increased from one thousand rupees to five thousand rupees in sub-section (4)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "261", titleEn: "Compliance with section 230", oldSection: "238", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "262", titleEn: "When accused shall be discharged", oldSection: "239", comparisonNote: "New subsection 262(1) provides the time limit of application for discharge by accused as \"within a period of sixty days from the date of supply of copies of document under section 230\". Examination of accused through audio- video electronic means can be done as added in sub-section (2)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "263", titleEn: "Framing of charge", oldSection: "240", comparisonNote: "Time limit for framing of charge against the accused is added within a period of sixty days from the date of first hearing on charge"),
  LegalIndexRecord(code: LegalCode.bnss, section: "264", titleEn: "Conviction on plea of guilty", oldSection: "241", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "265", titleEn: "Evidence for prosecution", oldSection: "242", comparisonNote: "The new proviso to subsection 265(3) of the BNSS states that evidence of a witness may be recorded by audio-video electronic means at the designated place to be notified by the State Government"),
  LegalIndexRecord(code: LegalCode.bnss, section: "266", titleEn: "Evidence for defence", oldSection: "243", comparisonNote: "New second proviso to Section 266(2) provides that the examination of witnesses may be done by audio-video electronic means at the designated place to be notified by the State Government"),
  LegalIndexRecord(code: LegalCode.bnss, section: "267", titleEn: "Evidence for prosecution", oldSection: "244", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "268", titleEn: "When accused shall be discharged", oldSection: "245", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "269", titleEn: "Procedure where accused is not discharged", oldSection: "246", comparisonNote: "The newly added subsection (7) provides that if the attendance of the prosecution witnesses under sub-sections (5) and (6) cannot be secured for cross-examination, it shall be deemed that such witness has not been examined for not being available and Magistrate proceed further"),
  LegalIndexRecord(code: LegalCode.bnss, section: "270", titleEn: "Evidence for defence", oldSection: "247", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "271", titleEn: "Acquittal or conviction", oldSection: "248", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "272", titleEn: "Absence of complainant", oldSection: "249", comparisonNote: "It is added that the Magistrate may “after giving thirty days’ time to the complainant to be present before proceeding further"),
  LegalIndexRecord(code: LegalCode.bnss, section: "273", titleEn: "Compensation for accusation without reasonable cause", oldSection: "250", comparisonNote: "BNS Sections replace corresponding IPC sections Compensation amount under sub-section (6) increased from \"one hundred rupees\" to “two thousand rupees”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "274", titleEn: "Substance of accusation to be stated", oldSection: "251", comparisonNote: "The new proviso to Section 274 provides that if the Magistrate considers the accusation groundless, he shall, after recording reasons in writing, release the accused, and such release shall have the effect of discharge"),
  LegalIndexRecord(code: LegalCode.bnss, section: "275", titleEn: "Conviction on plea of guilty", oldSection: "252", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "276", titleEn: "Conviction on plea of guilty in absence of accused in petty cases", oldSection: "253", comparisonNote: "\"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "277", titleEn: "Procedure when not convicted", oldSection: "254", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "278", titleEn: "Acquittal or conviction", oldSection: "255", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "279", titleEn: "Non-appearance or death of complainant", oldSection: "256", comparisonNote: "The words \"after giving thirty days' time to the complainant to be present\" are added \"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "280", titleEn: "Withdrawal of complaint", oldSection: "257", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "281", titleEn: "Power to stop proceedings in certain cases", oldSection: "258", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "282", titleEn: "Power of Court to convert summons-cases into warrant- cases", oldSection: "259", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "283", titleEn: "Power to try summarily", oldSection: "260", comparisonNote: "BNS sections replace Corresponding IPC sections. Sub section (2) is newly added with a proviso to it for trial of offences punishable with three or less than three years in a summary way. Provided that no appeal shall lie against the decision of a Magistrate to try a case in a summary way under this sub-section"),
  LegalIndexRecord(code: LegalCode.bnss, section: "284", titleEn: "Summary trial by Magistrate of the second class", oldSection: "261", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "285", titleEn: "Procedure for summary trials", oldSection: "262", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "286", titleEn: "Record in summary trials", oldSection: "263", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "287", titleEn: "Judgment in cases tried summarily", oldSection: "264", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "288", titleEn: "Language of record and judgment", oldSection: "265", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "289", titleEn: "Application of the Chapter", oldSection: "265A", comparisonNote: "\"Below the age of fourteen years\" excluded from 289(1)(b), thereby expanding the scope"),
  LegalIndexRecord(code: LegalCode.bnss, section: "290", titleEn: "Application for plea bargaining", oldSection: "265B", comparisonNote: "Time limit for plea bargaining \"within a period of thirty days from the date of framing of charge\" is added in subsection (1) 290 (4) (a) \"not exceeding sixty days\" is added, regarding accused to work out a mutually satisfactory disposition of the case\". The words “as the case may be” excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "291", titleEn: "Guidelines for mutually satisfactory disposition", oldSection: "265C", comparisonNote: "\"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "292", titleEn: "Report of the mutually satisfactory disposition to be submitted before the Court", oldSection: "265D", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "293", titleEn: "Disposal of the case", oldSection: "265E", comparisonNote: "Section 293 clauses (c ) and (d) make changes to require the court to show leniency towards first -time offenders who opt for plea bargaining. They may be sentenced to one fourth of minimum punishment instead of half and one- nineth instead of one-fourth respectively"),
  LegalIndexRecord(code: LegalCode.bnss, section: "294", titleEn: "Judgment of the Court", oldSection: "265F", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "295", titleEn: "Finality of the judgment", oldSection: "265G", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "296", titleEn: "Power of the Court in plea bargaining", oldSection: "265H", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "297", titleEn: "Period of detention undergone by the accused to be set off against the sentence of imprisonment", oldSection: "", comparisonNote: "265-I No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "298", titleEn: "Savings", oldSection: "265J", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "299", titleEn: "Statements of accused not to be used", oldSection: "265K", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "300", titleEn: "Non-application of the Chapter", oldSection: "265L", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "301", titleEn: "Definitions", oldSection: "266", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "302", titleEn: "Power to require attendance of prisoners", oldSection: "267", comparisonNote: "The words “as the case may be” are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "303", titleEn: "Power of State Government or Central Government to exclude certain persons from operation of section 302", oldSection: "268", comparisonNote: "\"or Central Government\" is added in the heading and other places. \"the Central Government in the cases instituted by its central agency, as the case may be\" are added in subsection (2)"),
  LegalIndexRecord(code: LegalCode.bnss, section: "304", titleEn: "Officer in charge of prison to abstain from carrying out order in certain contingencies", oldSection: "269", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "305", titleEn: "Prisoner to be brought to Court in custody", oldSection: "270", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "306", titleEn: "Power to issue commission for examination of witness in prison", oldSection: "271", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "307", titleEn: "Language of Courts", oldSection: "272", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "308", titleEn: "Evidence to be taken in presence of accused", oldSection: "273", comparisonNote: "The words \"through audio-video electronic means at the designated place to be notified by the State Government\" are added"),
  LegalIndexRecord(code: LegalCode.bnss, section: "309", titleEn: "Record in summons-cases and inquiries", oldSection: "274", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "310", titleEn: "Record in warrant-cases", oldSection: "275", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "311", titleEn: "Record in trial before Court of Session", oldSection: "276", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "312", titleEn: "Language of record of evidence", oldSection: "277", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "313", titleEn: "Procedure in regard to such evidence when completed", oldSection: "278", comparisonNote: "The word \"pleader\" is replaced by \"advocate\" in heading and other places"),
  LegalIndexRecord(code: LegalCode.bnss, section: "314", titleEn: "Interpretation of evidence to accused or his pleader", oldSection: "279", comparisonNote: "Ditto"),
  LegalIndexRecord(code: LegalCode.bnss, section: "315", titleEn: "Remarks respecting demeanour of witness", oldSection: "280", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "316", titleEn: "Record of examination of accused", oldSection: "281", comparisonNote: "\"a Metropolitan Magistrate\" is replaced by \"any Magistrate, or by a Court of Session,\" and sub-sections related to a metropolitan Magistrate are excluded. A new proviso is added to 316 (4) \"where the accused is in custody and is examined through electronic communication, his signature shall be taken within seventy-two hours of such examination.”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "317", titleEn: "Interpreter to be bound to interpret truthfully", oldSection: "282", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "318", titleEn: "Record in High Court", oldSection: "283", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "319", titleEn: "When attendance of witness may be dispensed with and commission issued", oldSection: "284", comparisonNote: "\"pleader\" is replaced by \"advocate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "320", titleEn: "Commission to whom to be issued", oldSection: "", comparisonNote: "285 “Chief Metropolitan Magistrate\" excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "321", titleEn: "Execution of commissions", oldSection: "286", comparisonNote: "\"Chief Metropolitan Magistrate or Chief Judicial Magistrate, or such Metropolitan or Judicial Magistrate\" is replaced by \"Chief Judicial Magistrate or such Magistrate\""),
  LegalIndexRecord(code: LegalCode.bnss, section: "322", titleEn: "Parties may examine witnesses", oldSection: "287", comparisonNote: "The word “pleader” is replaced by “advocate”. “as the case may be” excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "323", titleEn: "Return of commission", oldSection: "288", comparisonNote: "BSA sections replace corresponding Indian Evidence Act sections"),
  LegalIndexRecord(code: LegalCode.bnss, section: "324", titleEn: "Adjournment of proceeding", oldSection: "289", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "325", titleEn: "Execution of foreign commissions", oldSection: "290", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "326", titleEn: "Deposition of medical witness", oldSection: "291", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "327", titleEn: "Identification report of Magistrate", oldSection: "291A", comparisonNote: "BSA sections replace corresponding Indian Evidence Act sections"),
  LegalIndexRecord(code: LegalCode.bnss, section: "328", titleEn: "Evidence of officers of the Mint", oldSection: "292", comparisonNote: "BSA sections replace corresponding Indian Evidence Act sections. “any such”, “of the mint officer” and “as the case may be” are excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "329", titleEn: "Reports of certain Government scientific experts", oldSection: "293", comparisonNote: "In 329(4) (g) the words \"State Government or, and or certified \"are added and, “Government” excluded"),
  LegalIndexRecord(code: LegalCode.bnss, section: "330", titleEn: "No formal proof of certain documents", oldSection: "294", comparisonNote: "Two new provisos are added. Time limit of thirty days for acceptance or denial of the genuineness of the document, provided the Court may relax the time limit as stated in the first proviso. And the second proviso states that experts should be called only if he is disputed by any parties during the trial. The words “may be prescribed by the State Government” is replaced by “the State Government may, by rules, provide”"),
  LegalIndexRecord(code: LegalCode.bnss, section: "331", titleEn: "Affidavit in proof of conduct of public servants", oldSection: "295", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "332", titleEn: "Evidence of formal character on affidavit", oldSection: "296", comparisonNote: "No change"),
  LegalIndexRecord(code: LegalCode.bnss, section: "333", titleEn: "Authorities before whom affidavits may be sworn", oldSection: "297", comparisonNote: "No change"),
